#!/usr/bin/env python3
"""Génère le HTML accessible à partir des sorties exécutées par le moteur 4.23."""
from pathlib import Path
import json,html
root=Path(__file__).resolve().parent.parent
D=root/'dist'; obj=json.loads((D/'validation/empirique-423.json').read_text())
E=lambda s:html.escape(str(s),quote=True)
fmt=lambda v:(f'{v:+.2f}'.replace('.',',')).replace('-', '−')
cases={r['caseId']:r for r in obj['records'] if r['horizon']==1}
cases3={r['caseId']:r for r in obj['records'] if r['horizon']==3}
rows=''
for s in obj['studies']:
 r1=cases[s['ecosimCase']];r3=cases3[s['ecosimCase']]
 rows+=f'''<tr><th scope="row"><a href="{E(s['url'])}">{E(s['theme'])}</a><small class="empirical-source">{E(s['publisher'])} · {E(s['year'])}</small></th>
 <td>{E(s['reported'])}</td><td>{fmt(r1['deltaGdpPct'])} % (1 an), {fmt(r3['deltaGdpPct'])} % (3 ans)<small class="empirical-source">Choc EcoSim distinct : {E(r1['label'])}</small></td>
 <td><strong>{E(s['comparability'])}</strong><small class="empirical-source">{E(s['limitation'])}</small></td></tr>'''
sections=''
for i,s in enumerate(obj['studies'],1):
 sections+=f'''<section aria-labelledby="etude-{i}"><h2 id="etude-{i}">{i}. {E(s['theme'])}</h2><p><strong>Source :</strong> <a href="{E(s['url'])}">{E(s['publisher'])}, {E(s['year'])} — {E(s['title'])}</a>, {E(s['authors'])}.</p><p><strong>Méthode :</strong> {E(s['method'])}.</p><p><strong>Constat externe :</strong> {E(s['reported'])}</p><p><strong>Ce que simule EcoSim :</strong> {E(cases[s['ecosimCase']]['label'])}. À 1 an, l'écart conditionnel de PIB est {fmt(cases[s['ecosimCase']]['deltaGdpPct'])} % ; à 3 ans, {fmt(cases3[s['ecosimCase']]['deltaGdpPct'])} %.</p><div class="guide-callout"><strong>Comparabilité : {E(s['comparability'])}</strong><p>{E(s['limitation'])}</p><p><strong>Conclusion :</strong> {E(s['conclusion'])}</p></div></section>'''
page=f'''<!doctype html>
<html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="index,follow"><meta name="description" content="EcoSim 4.23 : confrontation prudente à quatre évaluations indépendantes (Insee, IPP, France Stratégie), correspondance des chocs, limites et données reproductibles."><link rel="canonical" href="https://nicolasmoreau1982-beep.github.io/evaluations-empiriques-423.html"><meta property="og:image" content="https://nicolasmoreau1982-beep.github.io/og-ecosim.png"><meta name="twitter:card" content="summary_large_image"><title>Études empiriques et limites de comparaison — EcoSim France 4.23</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="guides.css"><script src="theme.js"></script>
<style>.empirical-scroll{{overflow-x:auto;margin:1.2rem 0}}.empirical-scroll table{{border-collapse:collapse;width:100%;min-width:760px;font-size:14px;line-height:1.5}}.empirical-scroll th,.empirical-scroll td{{padding:12px;border-bottom:1px solid #9997;text-align:left;vertical-align:top}}.empirical-scroll caption{{text-align:left;margin:.5rem 0 1rem;font-weight:650}}.empirical-source{{display:block;font-size:13px;line-height:1.5;margin:.35rem 0;color:var(--ink-soft,#526064)}}.empirical-links{{display:flex;flex-wrap:wrap;gap:1rem;margin:1rem 0}}.empirical-links a{{overflow-wrap:anywhere}}</style></head>
<body><a class="skip-link" href="#main">Aller au contenu</a><header class="guide-header"><a class="brand" href="index.html">EcoSim <b>France</b></a><nav class="guide-nav" aria-label="Navigation"><a href="index.html">Simulateur</a><a href="audit.html">Audit</a><a href="sensibilite-multiplicateurs-422.html">Sensibilité</a></nav></header>
<main id="main" class="guide-main"><p class="guide-breadcrumb"><a href="index.html">Accueil</a> / Études empiriques</p>
<div class="guide-hero"><span class="guide-kicker">EcoSim 4.23 · 11 octobre 2026</span><h1>Qu'apprenons-nous des réformes réellement observées ?</h1><p class="guide-lead">Quatre études françaises indépendantes des hypothèses d'EcoSim sont confrontées à quatre exemples générés par le moteur. <strong>Aucun exemple ne reproduit encore exactement le choc et l'indicateur de l'étude</strong> : ce travail documente les écarts de périmètre, pas un score de fiabilité scientifique.</p></div>
<div class="guide-callout"><strong>Résultat de comparabilité : 0 correspondance stricte</strong><p>Une comparaison partielle sur les dépenses publiques, trois comparaisons non équivalentes (TVA, retraites, CICE). <strong>Aucun écart de prédiction ou taux d'erreur causal n'est calculé</strong> : comparer des grandeurs différentes donnerait une précision trompeuse.</p></div>
<section aria-labelledby="synthese"><h2 id="synthese">Tableau de confrontation</h2><p>Les chiffres EcoSim sont des effets conditionnels par rapport à sa propre trajectoire de référence ; les chiffres des études portent sur d'autres populations, variables ou périodes. Ils ne doivent pas être soustraits pour conclure que le moteur réussit ou échoue.</p><div class="empirical-scroll"><table><caption>Études indépendantes, exemple EcoSim et limites de comparabilité (version 4.23)</caption><thead><tr><th scope="col">Étude</th><th scope="col">Résultat externe</th><th scope="col">Écart de PIB EcoSim</th><th scope="col">Statut</th></tr></thead><tbody>{rows}</tbody></table></div></section>
{sections}
<section aria-labelledby="limites"><h2 id="limites">Ce que ces confrontations ne valident pas</h2><p>Le coefficient d'une réforme peut dépendre du calendrier, de sa cible, du financement, des anticipations, de la période monétaire et de la conjoncture. Les estimations historiques et les simulations prospectives ne sont pas directement interchangeables. L'étude Insee sur le multiplicateur porte sur des biens et services ; le proxy fonctionnel COFOG utilisé par EcoSim n'est pas cette nomenclature économique.</p><p>La prochaine véritable validation nécessiterait d'ajouter un levier reproduisant <em>exactement</em> une réforme documentée (éligibilité, calendrier, montant, population), puis de comparer une <em>même grandeur</em> sur un horizon aligné, sur des données jamais utilisées pour calibrer les paramètres.</p><p>Les coefficients du moteur central 4.22 ont été conservés à l'identique en 4.23. Aucun rapprochement documentaire n'a servi à les recalibrer.</p><p class="empirical-links"><a href="validation/empirique-423.json">Exporter les études et scénarios (JSON)</a><a href="validation/empirique-423.csv">Exporter les résultats EcoSim (CSV)</a><a href="audit.html#evaluations-423">Lire le protocole dans l'audit</a></p></section>
</main><footer class="guide-footer"><span>EcoSim France · Version 4.23 · paquet <code>PAQUET_A_REMPLACER</code></span><a href="confidentialite.html">Confidentialité</a></footer></body></html>'''
(D/'evaluations-empiriques-423.html').write_text(page)
print('Rapport 4.23 pré-généré :',len(obj['studies']),'études,',len(obj['records']),'résultats')
